    Packages.android.util,
    Packages.java.lang,
    Packages.java.io,
    Packages.android.graphics
);
with(Magua) {
  function decode(imgBytes, width, height) {
    var bmp = BitmapFactory.decodeByteArray(imgBytes, 0, imgBytes.length);

    var bmpWidth = bmp.getWidth();
    var bmpHeight = bmp.getHeight();

    // 判断误差小于200直接返回图片bytes
    //ycy.toast("误差：" + Math.abs(((bmpWidth/width) * height) - bmpHeight));
    if (200 > Math.abs(((bmpWidth/width) * height) - bmpHeight)) {
      return imgBytes;
    }
    //ycy.toast("bmp宽高: " + bmpWidth + "    " + bmpHeight);
    var mScreenWidth = width;
    var mScreenHeight = height;
    var newbit = Bitmap.createScaledBitmap(bmp, mScreenWidth, mScreenHeight, true);
    var baos = new ByteArrayOutputStream();
    newbit.compress(Bitmap.CompressFormat.PNG, 100, baos);
    return baos.toByteArray();
  }
}
if (img.width == 1 && img.height == 1){
    result;
} else {
    decode(result, img.width, img.height);
}

